package com.ghatana.media.integration;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.TimeUnit;

/**
 * Real input and independent measurement for the J-19 quality optimization journey. The source is generated by FFmpeg
 * ({@code testsrc2} moving pattern plus seeded temporal noise at 640x360, 25 fps, 2 s, AAC tone, near-lossless CRF 10)
 * so that re-encoding it at different CRFs gives a wide, genuine quality/size trade-off. The independent encode uses
 * the documented lane command line and the independent measurement uses FFmpeg's own {@code ssim}/{@code psnr}
 * filters, never the product's Java metrics.
 */
final class QualityOptimizationFixture {
    private QualityOptimizationFixture() { }

    static byte[] noisySource(Path ffmpeg, Path work) throws Exception {
        Path out = work.resolve("noisy-source.mp4");
        run(List.of(ffmpeg.toString(), "-nostdin", "-v", "error", "-f", "lavfi", "-i",
                "testsrc2=size=640x360:rate=25:duration=2,noise=alls=5:allf=t:all_seed=7",
                "-f", "lavfi", "-i", "sine=frequency=440:sample_rate=48000:duration=2",
                "-c:v", "libx264", "-preset", "medium", "-crf", "10", "-pix_fmt", "yuv420p",
                "-c:a", "aac", "-b:a", "64k", "-shortest", "-y", out.toString()));
        return Files.readAllBytes(out);
    }

    /** The lane's documented encode, run independently of the product: identical inputs give identical bytes. */
    static byte[] independentEncode(Path ffmpeg, Path work, Path source, int crf, String comment) throws Exception {
        Path out = work.resolve("independent-" + crf + ".mp4");
        run(List.of(ffmpeg.toString(), "-nostdin", "-hide_banner", "-v", "error", "-xerror", "-i", source.toString(),
                "-map", "0:v:0", "-map", "0:a?", "-sn", "-dn", "-c:v", "libx264", "-preset", "medium", "-crf",
                Integer.toString(crf), "-pix_fmt", "yuv420p", "-threads", "1", "-fps_mode", "passthrough", "-fflags",
                "+bitexact", "-flags:v", "+bitexact", "-map_metadata", "-1", "-metadata", "comment=" + comment, "-c:a", "copy", "-y",
                out.toString()));
        return Files.readAllBytes(out);
    }

    /** The documented per-request container comment: a fixed-length digest of tenant, principal and requestId. */
    static String containerComment(String tenant, String principal, String requestId) throws Exception {
        byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
                .digest((tenant + "\u0000" + principal + "\u0000" + requestId).getBytes(java.nio.charset.StandardCharsets.UTF_8));
        return "media-dev-quality " + java.util.HexFormat.of().formatHex(digest).substring(0, 32);
    }

    /** SHA-256 of the video packets only (container and comment excluded), measured by FFmpeg's hash muxer. */
    static String streamSha256(Path ffmpeg, Path video) throws Exception {
        Process process = new ProcessBuilder(ffmpeg.toString(), "-nostdin", "-v", "error", "-i", video.toString(), "-map",
                "0:v:0", "-c", "copy", "-f", "hash", "-hash", "sha256", "-").redirectErrorStream(true).start();
        String text = new String(process.getInputStream().readAllBytes()).trim();
        if (!process.waitFor(120, TimeUnit.SECONDS) || process.exitValue() != 0 || !text.startsWith("SHA256=")) {
            throw new IllegalStateException("stream hash failed: " + text);
        }
        return text.substring("SHA256=".length());
    }

    private static void run(List<String> command) throws Exception {
        Process process = new ProcessBuilder(command).redirectErrorStream(true).start();
        byte[] log = process.getInputStream().readAllBytes();
        if (!process.waitFor(300, TimeUnit.SECONDS) || process.exitValue() != 0) {
            throw new IllegalStateException(command.get(0) + " failed: " + new String(log));
        }
    }
}
